// Coordenada de verdade: número finito. CUIDADO: isFinite(null) é true em JavaScript — um pluviômetro
// sem posição (lat: null) passava como se tivesse e derrubava a tela (queda do Vitor, 17/09/2026).
function coordOk(v) { return v !== null && v !== undefined && v !== "" && typeof v !== "boolean" && isFinite(v); }

