// "entrou 06/09 às 14:32" — última abertura do app pela pessoa (hora do aparelho de quem vê)
function fmtQuando(iso) {
  if (!iso) return "nunca entrou";
  const d = new Date(iso);
  if (isNaN(d)) return "nunca entrou";
  const dd = String(d.getDate()).padStart(2, "0"), mm = String(d.getMonth() + 1).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0"), mi = String(d.getMinutes()).padStart(2, "0");
  const dias = Math.floor((Date.now() - d.getTime()) / 86400000);
  return `${dd}/${mm}${d.getFullYear() !== new Date().getFullYear() ? "/" + d.getFullYear() : ""} às ${hh}:${mi}${dias === 0 ? " (hoje)" : dias === 1 ? " (ontem)" : dias > 30 ? ` (há ${dias} dias)` : ""}`;
}
