const CAMPO_VER = ["panorama", "dadosfazenda", "lavoura", "solo", "operacoes", "fungicidas", "estoque", "ndvi", "pluviometria", "colheita", "visitas", "comunidade", "suporte"];
const PADRAO_FUNCAO_EQUIPE = {
  "Produtor": { tudo: true },
  "Gerente": { tudo: true, nao: ["acessos"] },
  "Engenheiro agrônomo": { tudo: true, nao: ["custos", "simulacoes", "excluir", "acessos"] },
  "Escritório": { so: ["panorama", "estoque", "programa", "diesel", "almoxarifado", "financeiro", "custos", "cotacoes", "simulacoes", "relatorios", "documentos", "comunidade", "suporte", "cadastrar"] },
  "Monitor de campo": { so: CAMPO_VER },
  "Operador de máquinas": { so: ["panorama", "operacoes", "fungicidas", "estoque", "pluviometria", "colheita", "diesel", "almoxarifado", "comunidade", "suporte"] },
};
// valores antigos de função ("Monitor", "Operador", "Agrônomo") → nome atual da lista FUNCOES
const normalizarFuncao = (f) => {
  const s = semAcento(f || "");
  if (!s) return FUNCOES[0];
  const exata = FUNCOES.find((x) => semAcento(x) === s); if (exata) return exata;
  if (/monitor/.test(s)) return "Monitor de campo";
  if (/operador|tratorista|maquin/.test(s)) return "Operador de máquinas";
  if (/agronom|engenheir|tecnic/.test(s)) return "Engenheiro agrônomo";
  if (/gerent|administr/.test(s)) return "Gerente";
  if (/escrit|financ/.test(s)) return "Escritório";
  if (/produtor|dono|proprie/.test(s)) return "Produtor";
  return FUNCOES[0];
};
const permissoesDaFuncao = (funcao) => {
  const p = PADRAO_FUNCAO_EQUIPE[funcao]; if (!p) return {};
  const out = {};
  for (const [k] of ITENS_ACESSO) out[k] = p.tudo ? !(p.nao || []).includes(k) : (p.so || []).includes(k);
  return out;
};
const podeFazenda = (p, chave) => !!p && (p.permissoes && typeof p.permissoes[chave] === "boolean" ? p.permissoes[chave] : padraoAreaFazenda(p.funcao, chave));

