const SAFRA_INICIAL = "2026/2027";
// Fazendas que um acesso enxerga: as do login da nuvem, as do grupo,
// ou a que casa com o código.
function fazendasDoAcesso(perfil, fazendas, grupos) {
  if (!perfil) return [];
  if (Array.isArray(perfil.fazendasNuvem)) return (fazendas || []).filter((f) => perfil.fazendasNuvem.includes(f.id));
  if (perfil.grupoId) return (fazendas || []).filter((f) => f.grupoId === perfil.grupoId);
  const cod = (perfil.codigo || "").toUpperCase();
  return (fazendas || []).filter((f) => (f.codigo || "").toUpperCase() === cod && cod);
}
// Uma fazenda pertence a um grupo pelo grupoId OU, no jeito antigo,
// por carregar o CÓDIGO do grupo (fazendas cadastradas antes do grupoId).
const fazendaNoGrupo = (f, g) => !!f && !!g &&
  (f.grupoId === g.id || (!!g.codigo && (f.codigo || "").toUpperCase() === String(g.codigo).toUpperCase()));
// Fazendas irmãs (mesmo grupo): pelo grupoId ou pelo mesmo código
const saoIrmas = (a, b) => !!a && !!b && a.id !== b.id &&
  ((!!a.grupoId && a.grupoId === b.grupoId) || (!!a.codigo && (a.codigo || "").toUpperCase() === (b.codigo || "").toUpperCase()));

// Cada ciclo tem a SUA cultura: na safra vale a cultura dos talhões (soja),
// na safrinha a culturaSafrinha (milho). Nada de misturar sacas de um com o
// outro — custo, venda, estoque e DRE olham a cultura do ciclo.
function culturaDoCiclo(fazenda, ciclo) {
  const cont = {};
  for (const t of (fazenda && fazenda.talhoes) || []) {
    const c = ciclo === "Safrinha" ? t.culturaSafrinha : t.cultura;
    if (c) cont[c] = (cont[c] || 0) + num(t.areaHa);
  }
  const ordem = Object.keys(cont).sort((a, b) => cont[b] - cont[a]);
  return ordem[0] || (ciclo === "Safrinha" ? "Milho" : "Soja");
}
// área dos talhões que têm aquela cultura (na safra ou na safrinha)
// Talhões que têm LAVOURA no ciclo (pastagem e talhão sem cultura ficam fora): é por esta área
// que se divide o custo por hectare — pastagem não pode diluir o custo da soja (Varjão, 11/09).
const SEM_LAVOURA = ["Pastagem"];
function talhoesLavoura(fazenda, ciclo) {
  return ((fazenda && fazenda.talhoes) || []).filter((t) => { const c = ciclo === "Safrinha" ? t.culturaSafrinha : t.cultura; return c && !SEM_LAVOURA.includes(c); });
}
function areaLavoura(fazenda, ciclo) {
  return talhoesLavoura(fazenda, ciclo).reduce((s, t) => s + num(t.areaHa), 0);
}
function areaDaCultura(fazenda, cultura) {
  return ((fazenda && fazenda.talhoes) || []).reduce((s, t) => s + ((t.cultura === cultura || t.culturaSafrinha === cultura) ? num(t.areaHa) : 0), 0);
}
// culturas presentes na fazenda, safra primeiro
function culturasDaFazenda(fazenda) {
  const lista = [];
  for (const t of (fazenda && fazenda.talhoes) || []) { if (t.cultura && !lista.includes(t.cultura)) lista.push(t.cultura); }
  for (const t of (fazenda && fazenda.talhoes) || []) { if (t.culturaSafrinha && !lista.includes(t.culturaSafrinha)) lista.push(t.culturaSafrinha); }
  return lista.length ? lista : ["Soja"];
}
// última cotação regional em R$ de um produto (Disponível tem preferência)
function precoRegionalDe(cotacoes, produto) {
  const lista = (cotacoes || []).filter((c) => c.produto === produto && (c.moeda || "R$") === "R$").sort((x, y) => (x.data || "").localeCompare(y.data || ""));
  const disp = lista.filter((c) => (c.modalidade || "Disponível") === "Disponível");
  const alvo = disp.length ? disp[disp.length - 1] : lista[lista.length - 1];
  return alvo ? { valor: num(alvo.preco), data: alvo.data } : null;
}
// chave da produtividade estimada por safra e cultura (soja guarda no jeito antigo)
const chaveProdutividade = (safra, cultura) => (!cultura || cultura === "Soja" ? safra : `${safra}|${cultura}`);

const safrasDa = (fz) => (fz && fz.safras && fz.safras.length ? fz.safras : [SAFRA_INICIAL]);
// validade do produto: quantos dias faltam e o nível (vencido / perto = 60 dias / ok)
function situacaoValidade(iso, hoje) {
  if (!iso || !/^\d{4}-\d{2}-\d{2}/.test(iso)) return null;
  const dias = diasEntreISO(hoje || hojeISO(), iso);
  return { dias, nivel: dias < 0 ? "vencido" : dias <= 60 ? "perto" : "ok" };
}
// Lotes de uma linha do estoque com o que resta de cada um: o usado sai primeiro do lote que vence antes
// (lote sem validade fica por último). Só vale quando algum lote tem lote/validade informados.
function lotesComSaldo(linha) {
  const lotes = (linha && linha.lotes) || [];
  if (!lotes.some((x) => x.lote || x.validade)) return [];
  const ordem = lotes.map((x, i) => ({ ...x, i })).sort((a, b) => ((a.validade || "9999") + "").localeCompare((b.validade || "9999") + "") || a.i - b.i);
  let consumo = num(linha.usado) + num(linha.saidas);
  return ordem.map((x) => { const tira = Math.min(x.qtd, Math.max(0, consumo)); consumo -= tira; return { lote: x.lote || "", validade: x.validade || "", qtd: x.qtd, resta: Math.round((x.qtd - tira) * 1000) / 1000 }; });
}
// Dica de lote para um produto da receita: o lote que deve sair primeiro (vence antes) e se está vencido
function dicaLoteDe(estoque, nome) {
  const l = (estoque || []).find((x) => chaveProduto(x.produto) === chaveProduto(nome)); if (!l) return null;
  const vivo = lotesComSaldo(l).find((x) => x.resta > 0); if (!vivo || (!vivo.lote && !vivo.validade)) return null;
  const sv = vivo.validade ? situacaoValidade(vivo.validade) : null;
  const vencido = !!(sv && sv.nivel === "vencido");
  return { vencido, lote: vivo.lote, validade: vivo.validade, resta: vivo.resta, base: l.base,
    texto: `${vencido ? "⚠ lote vencido — confira antes de usar: " : "🧪 use primeiro: "}${vivo.lote ? `lote ${vivo.lote}` : "o que vence antes"}${vivo.validade ? ` · ${vencido ? "venceu" : "vence"} ${fmtD(vivo.validade)}` : ""} · ${fmtN(vivo.resta)} ${l.base}` };
}
// safra provável de uma data: a safra começa no meio do ano (julho) e vai até junho do ano seguinte
function safraDaData(dataISO) {
  const m = String(dataISO || "").match(/^(\d{4})-(\d{2})/); if (!m) return "";
  const ano = parseInt(m[1], 10), mes = parseInt(m[2], 10);
  return mes >= 7 ? `${ano}/${ano + 1}` : `${ano - 1}/${ano}`;
}
const safraAtualDe = (fz) => (fz && fz.safraAtual) || safrasDa(fz)[safrasDa(fz).length - 1];
// sugere a próxima: 2026/2027 -> 2027/2028
function proximaSafra(safra) {
  const p = String(safra).split("/").map((n) => parseInt(n, 10));
  return p.length === 2 && isFinite(p[0]) && isFinite(p[1]) ? `${p[0] + 1}/${p[1] + 1}` : "";
}

// Antes das safras, tudo morava numa chave sem safra. Ao abrir a primeira
// safra, o que já existia é trazido para dentro dela, uma única vez.
async function sGetSafra(chaveNova, chaveVelha, padrao) {
  const atual = await sGet(chaveNova, null);
  if (atual !== null && atual !== undefined) return atual;
  if (chaveVelha) {
    const antigo = await sGet(chaveVelha, null);
    if (antigo !== null && antigo !== undefined) {
      try { await sSet(chaveNova, antigo); } catch {}
      return antigo;
    }
  }
  return padrao;
}

// Dias entre uma data e hoje. É a conta que define janela de fungicida,
// carência e estádio — por isso ela se atualiza sozinha, sem ninguém lançar.
function diasDesde(iso) {
  if (!iso) return null;
  const d = new Date(iso + (iso.length === 10 ? "T12:00:00" : ""));
  if (isNaN(d)) return null;
  const hoje = new Date(); hoje.setHours(12, 0, 0, 0);
  return Math.round((hoje - d) / 86400000);
}

