const NOME_ATRIBUTO_SOLO = Object.fromEntries(ATRIBUTOS_SOLO);
// para estes, subir é bom; para Al e m%, descer é bom; pH não tem lado (depende da faixa)
const SOBE_E_BOM = new Set(["mo", "p", "pRes", "pMeh", "k", "ca", "mg", "sb", "ctc", "v", "s", "b", "cu", "fe", "mn", "zn"]);
const DESCE_E_BOM = new Set(["al", "hAl", "m"]);
// variação entre duas análises do mesmo atributo: seta, diferença e se é melhora
const tendenciaSolo = (chave, atual, anterior) => {
  const a = num(atual), b = num(anterior);
  if (!(isFinite(a) && isFinite(b)) || atual == null || anterior == null || atual === "" || anterior === "") return null;
  const dif = a - b;
  if (Math.abs(dif) < 1e-9) return { seta: "→", dif: 0, pct: 0, melhora: null };
  const pct = b !== 0 ? (dif / Math.abs(b)) * 100 : null;
  const melhora = SOBE_E_BOM.has(chave) ? dif > 0 : DESCE_E_BOM.has(chave) ? dif < 0 : null;
  return { seta: dif > 0 ? "↑" : "↓", dif, pct, melhora };
};
const ehAnaliseSolo = (x) => !x.tipo || x.tipo === "analise";
// profundidade normalizada: "0 a 20 cm", "00-20", "0–20" → "0-20"; sem número → ""
const profundidadeChave = (s) => { const nums = String(s == null ? "" : s).match(/\d+(?:[.,]\d+)?/g); if (!nums || !nums.length) return ""; const a = Number(nums[0].replace(",", ".")), b = nums[1] != null ? Number(nums[1].replace(",", ".")) : null; return b != null ? `${a}-${b}` : `${a}`; };
const rotuloProfundidade = (k) => (k ? `${k.replace("-", "–")} cm` : "profundidade não informada");
