const pontosDoGrid = (areaHa, gridHa) => (num(areaHa) > 0 && num(gridHa) > 0 ? Math.max(1, Math.round(num(areaHa) / num(gridHa))) : 0);
// Dois grids num furo só: dos pontos de 0–20 (finos), escolhe os que também recebem 20–40 (grid mais
