const fmtValorSolo = (v) => (v == null || v === "" ? "—" : typeof v === "number" ? fmtN(Math.round(v * 100) / 100) : String(v));

// escala de cor da fertilidade: vermelho (baixo) → laranja → amarelo → verde-claro → verde (alto).
// Para o que é ruim quando alto (Al, H+Al, m%), a escala inverte.
const CORES_SOLO = [[214, 69, 65], [242, 153, 74], [247, 214, 96], [168, 214, 120], [46, 139, 87]];
