// g/dm³ (M.O.), % (V, m, argila). Para m% a ordem inverte: baixo é bom. Argila é textura, não fertilidade.
const FAIXAS_SOLO = {
  ph: [4.5, 5.2, 6.0], mo: [15, 25, 35], pRes: [6, 15, 40], k: [0.7, 1.5, 3.0], ca: [15, 30, 45], mg: [4, 8, 12], s: [5, 10, 40],
  ctc: [40, 60, 80], v: [30, 50, 70], m: [10, 20, 45],
  b: [0.35, 0.6, 0.9], cu: [0.35, 0.6, 0.9], zn: [0.9, 1.5, 2.2], mn: [5, 8, 12], fe: [8, 12, 30],
  argila: [15, 35, 60],
};
const CLASSES_SOLO = ["Baixo", "Médio", "Alto", "Muito alto"];
