  const textura = k === "argila";
  const nomes = textura ? CLASSES_TEXTURA : CLASSES_SOLO;
  const cores = textura ? CORES_TEXTURA : k === "m" ? CORES_CLASSE.slice().reverse() : CORES_CLASSE;
  const rot = [`< ${fmtN(lim[0])}`, `${fmtN(lim[0])}–${fmtN(lim[1])}`, `${fmtN(lim[1])}–${fmtN(lim[2])}`, `> ${fmtN(lim[2])}`];
