  const [modo, setModo] = useState("ver");          // ver · desenhar · andar
  const [rascunho, setRascunho] = useState([]);     // pontos [lng, lat] do talhão em andamento
  const [fechando, setFechando] = useState(null);   // {aneis, areaHa} esperando o nome
  const [nomeNovo, setNomeNovo] = useState("");
  const [selecionado, setSelecionado] = useState(null);
  const [posicao, setPosicao] = useState(null);     // {lng, lat, prec}
  const [gravando, setGravando] = useState(false);  // modo andar: GPS acrescentando pontos sozinho
  const [passoM, setPassoM] = useState("5");
  const [busca, setBusca] = useState("");
  const [msg, setMsg] = useState("");
  const [criarTalhoes, setCriarTalhoes] = useState(true);
  const vistaRef = useRef(vista); vistaRef.current = vista;
  const rascunhoRef = useRef(rascunho); rascunhoRef.current = rascunho;
  // mapa que a fazenda já tem: polígono tocado e contorno em correção (cantos arrastáveis)
  const [kmlSel, setKmlSel] = useState(null);       // índice em kml.poligonos
  const [editando, setEditando] = useState(null);   // {idx, pts: [[lng, lat]…] (anel aberto)}
  const [cantoSel, setCantoSel] = useState(null);
  const editandoRef = useRef(editando); editandoRef.current = editando;

  // procura o município da fazenda na primeira vez, quando não há de onde tirar o lugar
  useEffect(() => {
    if (temKml || (fazenda.pluviometros || []).some((m) => coordOk(m.lat)) || !fazenda.municipio) return;
    procurarLugar(String(fazenda.municipio).replace("/", " ") + " Brasil", 12, true);
  }, []);
  async function procurarLugar(texto, zoom, silencioso) {
    const t = String(texto || "").trim(); if (!t) return;
    const coord = t.match(/^\s*(-?\d+(?:[.,]\d+)?)\s*[,; ]\s*(-?\d+(?:[.,]\d+)?)\s*$/);
    if (coord) {
      const a = Number(coord[1].replace(",", ".")), b = Number(coord[2].replace(",", "."));
      setVista({ lat: a, lng: b, z: 16 }); setMsg(""); return;
    }
    try {
      if (!silencioso) setMsg("Procurando…");
      const r = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=br&accept-language=pt-BR&q=${encodeURIComponent(t)}`);
      const j = await r.json();
      if (j && j[0]) { setVista({ lat: Number(j[0].lat), lng: Number(j[0].lon), z: zoom || 14 }); setMsg(""); }
      else if (!silencioso) setMsg("Não achei esse lugar. Tente o nome da cidade, ou cole as coordenadas (ex.: -11.70, -49.10).");
    } catch (e) { if (!silencioso) setMsg("Sem internet para procurar o lugar. Use 📍 Onde estou ou cole as coordenadas."); }
  }

  // GPS ligado nos modos de campo (e quando pede "onde estou")
  const [seguirGps, setSeguirGps] = useState(false);
  const telaAcesaMapa = useTelaAcesa(modo === "andar");
  useEffect(() => {
    if (!(modo === "andar" || seguirGps) || !navigator.geolocation) return;
    const id = navigator.geolocation.watchPosition((p) => {
      const pos = { lng: p.coords.longitude, lat: p.coords.latitude, prec: p.coords.accuracy };
      setPosicao(pos);
      if (seguirGps) { setVista((v) => ({ ...v, lat: pos.lat, lng: pos.lng, z: Math.max(v.z, 16) })); setSeguirGps(false); }
    }, () => { setMsg("Não consegui a posição do GPS — confira se a localização está ligada e liberada para o app."); setSeguirGps(false); },
    { enableHighAccuracy: true, maximumAge: 2000, timeout: 30000 });
    return () => { try { navigator.geolocation.clearWatch(id); } catch (e) {} };
  }, [modo, seguirGps]);
  // gravando andando: acrescenta ponto a cada X metros, com GPS de boa precisão; o mapa acompanha
