  if (semPosicao) avisos.push(`${semPosicao} ponto${semPosicao > 1 ? "s" : ""} sem posição (sem latitude/longitude e sem número igual ao dos pontos marcados) — entram na média, mas não no mapa.`);
  const lista = Object.values(grupos).map((g) => { const tt = talhoes.find((x) => x.id === g.talhaoId); return { ...g, nome: tt ? tt.nome : "?", unidades, comPosicao: g.pontos.filter((p) => p.lat != null).length, atributos: [...new Set(g.pontos.flatMap((p) => Object.keys(p.valores)))] }; });
