  const data = new Date(new Date(base + "T12:00:00").getTime() + ciclo * 86400000).toISOString().slice(0, 10);
  const faltam = Math.round((new Date(data + "T12:00:00") - new Date((hoje || hojeISO()) + "T12:00:00")) / 86400000);
  return { data, faltam, peloPlantio: !dataEmergencia };
