function dicasDaCalda(produtos, infoDe) {
  const grupos = new Set();
  for (const p of produtos || []) { if (!p || !p.nome) continue; grupos.add(grupoMistura(p.nome, infoDe ? infoDe(p.nome) : null)); }
  const out = [];
  if (grupos.has(1)) out.push(DICAS_CALDA.po);
  if (grupos.has(2)) out.push(DICAS_CALDA.sc);
  if (grupos.has(3)) out.push(DICAS_CALDA.ec);
  if (grupos.has(4)) out.push(DICAS_CALDA.sl);
  if (grupos.has(5)) out.push(DICAS_CALDA.foliar);
  if (grupos.has(6)) out.push(DICAS_CALDA.oleo);
  if (grupos.has(7)) out.push(DICAS_CALDA.bio);
  return out;
}
function ordemDeMistura(produtos, infoDe) {
  const lista = (produtos || []).filter((p) => p && p.nome);
  const com = lista.map((p, i) => ({ p, i, g: grupoMistura(p.nome, infoDe ? infoDe(p.nome) : null), info: infoDe ? infoDe(p.nome) : {} }));
  const ordenados = com.slice().sort((a, b) => a.g - b.g || a.i - b.i);
  const jaCerta = ordenados.every((x, k) => x.i === com[k].i);
  const avisos = [];
  const txt = (x) => semAcento(x.p.nome + " " + ((x.info && x.info.ativo) || ""));
  const cat = (x) => semAcento((x.info && x.info.categoria) || "");
  const tem = (re) => com.filter((x) => re.test(txt(x)));
  const quimico = com.filter((x) => /fungicida|inseticida|acaricida|herbicida/.test(cat(x)) && x.g !== 7);
  if (com.some((x) => x.g === 7) && quimico.length) avisos.push("Biológico junto com químico: muitos não toleram — confira a compatibilidade na bula ou aplique separado. Se for junto, o biológico entra por último, com o tanque já cheio.");
  const glifo = tem(/glifosato|glyphosate/), cationicos = tem(/cobre|zinco|mangan|calcio|magnesio|\bferro\b/);
  if (glifo.length && cationicos.length) avisos.push(`Glifosato com ${cationicos.map((x) => x.p.nome).join(", ")}: cobre, zinco, manganês, cálcio e ferro travam o glifosato (antagonismo) — evite na mesma calda.`);
  const oleo = com.filter((x) => x.g === 6 && /oleo/.test(txt(x))), queima = tem(/enxofre|sulfur|clorotalonil|captan|captana/);
  if (oleo.length && queima.length) avisos.push(`Óleo com ${queima.map((x) => x.p.nome).join(", ")} pode queimar a folha (fitotoxicidade) — evite ou use dose baixa de óleo.`);
  const caB = tem(/calcio|\bboro\b|borax|acido borico/), fosSul = tem(/fosf|sulfat|map\b|dap\b/);
  if (caB.length && fosSul.length && caB.some((x) => !fosSul.includes(x))) avisos.push("Cálcio ou boro com fosfato/sulfato precipita no tanque (forma grumos) — não misture.");
  if (com.some((x) => x.g === 1)) avisos.push("Pós e grânulos (WG/WP): dissolva antes em água, com o tanque pela metade e a agitação ligada, antes dos líquidos.");
  if (com.length >= 4) avisos.push(`São ${com.length} produtos: faça o teste do jarro (misture a dose proporcional num balde) antes de encher o tanque.`);
  return { ordenados: ordenados.map((x) => x.p), grupos: ordenados.map((x) => ({ nome: x.p.nome, grupo: x.g, rotulo: GRUPOS_MISTURA[x.g] || "líquido" })), jaCerta, avisos };
}
// ---------- compras repetidas: somar ou lançar separado ----------
